// ─── SVG Charts ───────────────────────────────────────────────────────────────

type ChartType = 'bar' | 'line' | 'pie' | 'scatter';

function BarChart({ data, seriesNames, colors, W, H }: { data: { label: string; values: number[] }[]; seriesNames: string[]; colors: string[]; W: number; H: number }) {
  const { pad, w, h } = chartDims(W, H);
  const allVals = data.flatMap(d => d.values);
  const max = niceMax(Math.max(...allVals, 1));
  const lines = gridLines(max);
  const barW = (w / data.length) * 0.7;
  const gap = (w / data.length) * 0.15;

  return (
    <svg width={W} height={H}>
      <g transform={`translate(${pad.left},${pad.top})`}>
        {lines.map(v => {
          const y = h - (v / max) * h;
          return <g key={v}><line x1={0} y1={y} x2={w} y2={y} stroke={theme.colors.border} strokeWidth={1} /><text x={-8} y={y + 4} textAnchor="end" fontSize={10} fill={theme.colors.mainTextMuted}>{formatNum(v)}</text></g>;
        })}
        {data.map((d, di) => {
          const x = di * (w / data.length) + gap;
          return (
            <g key={di}>
              {d.values.map((v, si) => {
                const bh = (v / max) * h;
                return <rect key={si} x={x + si * (barW / d.values.length)} y={h - bh} width={barW / d.values.length - 2} height={bh} fill={colors[si % colors.length]} rx={2} opacity={0.9}><title>{d.label}: {formatNum(v)}</title></rect>;
              })}
              <text x={x + barW / 2} y={h + 16} textAnchor="middle" fontSize={10} fill={theme.colors.mainTextMuted}>{d.label}</text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}

function LineChart({ data, seriesNames, colors, W, H }: { data: { label: string; values: number[] }[]; seriesNames: string[]; colors: string[]; W: number; H: number }) {
  const { pad, w, h } = chartDims(W, H);
  const allVals = data.flatMap(d => d.values);
  const max = niceMax(Math.max(...allVals, 1));
  const lines = gridLines(max);
  const xStep = w / (data.length - 1 || 1);

  const numSeries = data[0]?.values.length ?? 1;

  return (
    <svg width={W} height={H}>
      <g transform={`translate(${pad.left},${pad.top})`}>
        {lines.map(v => {
          const y = h - (v / max) * h;
          return <g key={v}><line x1={0} y1={y} x2={w} y2={y} stroke={theme.colors.border} strokeWidth={1} /><text x={-8} y={y + 4} textAnchor="end" fontSize={10} fill={theme.colors.mainTextMuted}>{formatNum(v)}</text></g>;
        })}
        {Array.from({ length: numSeries }, (_, si) => {
          const pts = data.map((d, di) => ({ x: di * xStep, y: h - (d.values[si] / max) * h }));
          const path = pts.map((p, i) => `${i === 0 ? 'M' : 'L'}${p.x},${p.y}`).join(' ');
          return (
            <g key={si}>
              <path d={path} fill="none" stroke={colors[si % colors.length]} strokeWidth={2} />
              {pts.map((p, di) => (
                <circle key={di} cx={p.x} cy={p.y} r={4} fill={colors[si % colors.length]}>
                  <title>{data[di].label}: {formatNum(data[di].values[si])}</title>
                </circle>
              ))}
            </g>
          );
        })}
        {data.map((d, di) => (
          <text key={di} x={di * xStep} y={h + 16} textAnchor="middle" fontSize={10} fill={theme.colors.mainTextMuted}>{d.label}</text>
        ))}
      </g>
    </svg>
  );
}

function PieChart({ data, colors, W, H }: { data: { label: string; values: number[] }[]; colors: string[]; W: number; H: number }) {
  const R = Math.min(W, H) / 2 - 30;
  const cx = W / 2, cy = H / 2;
  const total = data.reduce((s, d) => s + (d.values[0] ?? 0), 0);
  let angle = -Math.PI / 2;
  const slices = data.map((d, i) => {
    const v = d.values[0] ?? 0;
    const sweep = (v / total) * 2 * Math.PI;
    const mid = angle + sweep / 2;
    const x1 = cx + R * Math.cos(angle), y1 = cy + R * Math.sin(angle);
    angle += sweep;
    const x2 = cx + R * Math.cos(angle), y2 = cy + R * Math.sin(angle);
    const large = sweep > Math.PI ? 1 : 0;
    const lx = cx + (R + 20) * Math.cos(mid), ly = cy + (R + 20) * Math.sin(mid);
    return { path: `M${cx},${cy} L${x1},${y1} A${R},${R} 0 ${large},1 ${x2},${y2} Z`, color: colors[i % colors.length], label: d.label, pct: ((v / total) * 100).toFixed(1), lx, ly, mid };
  });

  return (
    <svg width={W} height={H}>
      {slices.map((s, i) => (
        <g key={i}>
          <path d={s.path} fill={s.color} opacity={0.9} stroke={theme.colors.mainBg} strokeWidth={2}><title>{s.label}: {s.pct}%</title></path>
          {parseFloat(s.pct) > 3 && <text x={s.lx} y={s.ly} textAnchor="middle" dominantBaseline="middle" fontSize={10} fill={theme.colors.mainText}>{s.pct}%</text>}
        </g>
      ))}
    </svg>
  );
}

function ScatterChart({ data, colors, W, H }: { data: { label: string; values: number[] }[]; colors: string[]; W: number; H: number }) {
  const { pad, w, h } = chartDims(W, H);
  const xs = data.map(d => parseFloat(d.label));
  const ys = data.map(d => d.values[0] ?? 0);
  const maxX = niceMax(Math.max(...xs)), minX = Math.min(...xs);
  const maxY = niceMax(Math.max(...ys));
  const xLines = gridLines(maxX);
  const yLines = gridLines(maxY);
  const toX = (v: number) => ((v - minX) / (maxX - minX || 1)) * w;
  const toY = (v: number) => h - (v / maxY) * h;

  return (
    <svg width={W} height={H}>
      <g transform={`translate(${pad.left},${pad.top})`}>
        {yLines.map(v => (
          <g key={v}><line x1={0} y1={toY(v)} x2={w} y2={toY(v)} stroke={theme.colors.border} strokeWidth={1} /><text x={-8} y={toY(v) + 4} textAnchor="end" fontSize={10} fill={theme.colors.mainTextMuted}>{formatNum(v)}</text></g>
        ))}
        {xLines.map(v => (
          <text key={v} x={toX(v)} y={h + 16} textAnchor="middle" fontSize={10} fill={theme.colors.mainTextMuted}>{formatNum(v)}</text>
        ))}
        {data.map((d, i) => {
          const x = toX(parseFloat(d.label));
          const y = toY(d.values[0] ?? 0);
          return <circle key={i} cx={x} cy={y} r={5} fill={colors[0]} opacity={0.8}><title>{d.label}, {d.values[0]}</title></circle>;
        })}
      </g>
    </svg>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────

interface AppProps { topBarRight?: React.ReactNode; }

export default function App({ topBarRight }: AppProps) {
  const [type, setType] = useState<ChartType>('bar');
  const [csv, setCsv] = useState(EXAMPLES[0].csv);
  const [xCol, setXCol] = useState(EXAMPLES[0].xCol);
  const [yCols, setYCols] = useState(EXAMPLES[0].yCols);
  const [title, setTitle] = useState(EXAMPLES[0].title);
  const [palette, setPalette] = useState('Default');
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const h = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setMenuOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);

  const { headers, rows } = useMemo(() => parseChartData(csv), [csv]);
  const colors = PALETTES[palette] ?? PALETTES.Default;

  const chartData = useMemo(() => {
    if (!headers.length) return [];
    const xIdx = headers.indexOf(xCol);
    const yIdxs = yCols.map(y => headers.indexOf(y)).filter(i => i >= 0);
    if (xIdx < 0 || yIdxs.length === 0) return [];
    return rows.map(r => ({ label: r.label, values: yIdxs.map(yi => r.values[yi - 1] ?? 0) }));
  }, [headers, rows, xCol, yCols]);

  const numCols = headers.filter((_, i) => i > 0);

  const loadExample = (ex: typeof EXAMPLES[0]) => {
    setType(ex.type); setCsv(ex.csv); setXCol(ex.xCol); setYCols(ex.yCols); setTitle(ex.title); setMenuOpen(false);
  };

  const W = 600, H = 380;

  return (
    <Wrapper>
      <TopBar>
        <AtlantisLogo onClick={() => { window.location.hash = '#/home'; }} title="Home">Atl<span>antis</span></AtlantisLogo>
        <TitleSep>/</TitleSep>
        <AppTitle>Chart Builder<AppTitleSub>visualize data</AppTitleSub></AppTitle>
        <Spacer />
        <DropdownWrapper ref={menuRef}>
          <DropdownBtn onClick={() => setMenuOpen(o => !o)}>Examples <ChevronDown size={12} /></DropdownBtn>
          {menuOpen && (
            <DropdownMenu>
              {EXAMPLES.map(ex => (
                <DropdownItem key={ex.label} onClick={() => loadExample(ex)}>{ex.label}</DropdownItem>
              ))}
            </DropdownMenu>
          )}
        </DropdownWrapper>
        {topBarRight}
      </TopBar>

      <Body>
        <LeftPane>
          <Section>
            <SLabel>Chart Type</SLabel>
            <TypeBtns>
              {([['bar','Bar',BarChart2],['line','Line',TrendingUp],['pie','Pie',PieChartIcon],['scatter','Scatter',ScatterChartIcon]] as const).map(([t, label, Icon]) => (
                <TypeBtn key={t} active={type === t} onClick={() => setType(t as ChartType)}>
                  <Icon size={16} />{label}
                </TypeBtn>
              ))}
            </TypeBtns>
          </Section>

          <Section>
            <SLabel>Data (CSV)</SLabel>
            <DataArea value={csv} onChange={e => setCsv(e.target.value)} spellCheck={false} />
          </Section>

          {headers.length > 0 && (
            <>
              <Section>
                <SLabel>X Axis</SLabel>
                <Select value={xCol} onChange={e => setXCol(e.target.value)}>
                  {headers.map(h => <option key={h}>{h}</option>)}
                </Select>
              </Section>
              <Section>
                <SLabel>Y Axis</SLabel>
                <Select value={yCols[0]} onChange={e => setYCols([e.target.value])}>
                  {numCols.map(h => <option key={h}>{h}</option>)}
                </Select>
              </Section>
            </>
          )}

          <Section>
            <SLabel>Title</SLabel>
            <TitleInput value={title} onChange={e => setTitle(e.target.value)} placeholder="Chart title…" />
          </Section>

          <Section>
            <SLabel>Color Palette</SLabel>
            <PaletteRow>
              {Object.entries(PALETTES).map(([name, cols]) => (
                <PaletteBtn key={name} active={palette === name} onClick={() => setPalette(name)} title={name}>
                  {cols.slice(0, 4).map((c, i) => <PaletteDot key={i} color={c} />)}
                </PaletteBtn>
              ))}
            </PaletteRow>
          </Section>
        </LeftPane>

        <RightPane>
          {title && <ChartTitle>{title}</ChartTitle>}
          {chartData.length > 0 ? (
            <>
              {type === 'bar'     && <BarChart data={chartData} seriesNames={yCols} colors={colors} W={W} H={H} />}
              {type === 'line'    && <LineChart data={chartData} seriesNames={yCols} colors={colors} W={W} H={H} />}
              {type === 'pie'     && <PieChart data={chartData} colors={colors} W={W} H={H} />}
              {type === 'scatter' && <ScatterChart data={chartData} colors={colors} W={W} H={H} />}
              <Legend>
                {yCols.map((y, i) => (
                  <LegendItem key={y}><LegendDot color={colors[i % colors.length]} />{y}</LegendItem>
                ))}
              </Legend>
            </>
          ) : (
            <div style={{ color: theme.colors.mainTextMuted, fontSize: 14 }}>Enter CSV data and configure axes to see a chart</div>
          )}
        </RightPane>
      </Body>
    </Wrapper>
  );
}
